/**
 * Offline collocation table loading and the runtime entry point.
 *
 * `public/data/collocations.json` is generated by
 * `scripts/build-collocations.ts` and ships in the extension. The loader
 * fetches it through `chrome.runtime.getURL`, decodes the compact string array
 * into `CollocationEntry[]`, and caches one array (and its meta) per page.
 *
 * `computeOfflineSpans` is synchronous by contract: callers should await
 * [`loadCollocationTable`] during boot, after which every sentence matches from
 * memory. Without the extension runtime (or when the fetch fails) the loader
 * degrades to an empty table, so the overlay still renders.
 */

import type { CollocationSpan, Sentence } from '@/lib/contracts';
import { fetchExtensionJson } from '@/lib/data-assets';
import { getActiveDictionary, lemmatize } from '@/lib/dict';
import { isPlainRecord as isRecord } from '@/lib/utils/is-record';
import {
  buildCollocationIndex,
  matchIndexedCollocations,
  type CollocationEntry,
  type CollocationIndex,
} from './matcher';

export type { CollocationEntry } from './matcher';

/** Provenance/statistics shipped alongside the bigram list. */
export type CollocationMeta = {
  schema: 1;
  /** Content hash, e.g. `collocations-3f2a…`; changes with the data. */
  version: string;
  count: number;
  source: string;
  sourceUrl: string;
  license: string;
  attribution: string;
  filter: string;
  sourceRows: number;
  cleanedRows: number;
  filteredRows: number;
  rejected: { nonAscii: number; digit: number; markup: number };
};

/** On-disk shape of `public/data/collocations.json`. */
export type CollocationFile = {
  meta: CollocationMeta;
  /** Sorted by source score, descending. */
  bigrams: string[];
};

export type LoadCollocationOptions = {
  /** Alternate fetch implementation (tests/playground). */
  fetchImpl?: typeof fetch;
  /** Alternate asset URL; defaults to `chrome.runtime.getURL('data/collocations.json')`. */
  url?: string;
};

export type DecodedCollocationFile = {
  entries: CollocationEntry[];
  meta: CollocationMeta | null;
};

const ASSET_FILE = 'data/collocations.json';

let cachedEntries: CollocationEntry[] | null = null;
let cachedMeta: CollocationMeta | null = null;
let loading: Promise<CollocationEntry[]> | null = null;

let prepared: {
  table: readonly CollocationEntry[];
  dictionary: unknown;
  index: CollocationIndex;
} | null = null;

function decodeMeta(value: unknown): CollocationMeta | null {
  if (!isRecord(value) || value.schema !== 1) return null;
  if (
    typeof value.version !== 'string' ||
    typeof value.count !== 'number' ||
    typeof value.source !== 'string' ||
    typeof value.license !== 'string'
  ) {
    return null;
  }
  return value as CollocationMeta;
}

function decodeEntry(value: unknown): CollocationEntry | null {
  if (typeof value === 'string') {
    const text = value.trim();
    return text.length > 0 ? { text } : null;
  }
  if (!isRecord(value) || typeof value.text !== 'string') return null;
  const text = value.text.trim();
  if (text.length === 0) return null;

  const entry: CollocationEntry = { text };
  if (typeof value.score === 'number' && Number.isFinite(value.score)) {
    entry.score = value.score;
  }
  if (typeof value.type === 'string') entry.type = value.type;
  return entry;
}

function decodeEntries(values: readonly unknown[]): CollocationEntry[] {
  const entries: CollocationEntry[] = [];
  const seen = new Set<string>();
  for (const value of values) {
    const entry = decodeEntry(value);
    if (!entry || seen.has(entry.text)) continue;
    seen.add(entry.text);
    entries.push(entry);
  }
  return entries;
}

/**
 * Decode the shipped object (`{meta, bigrams}`) or a bare string array used by
 * fixtures. Invalid entries are skipped; a malformed container throws.
 */
export function decodeCollocationFile(payload: unknown): DecodedCollocationFile {
  if (Array.isArray(payload)) {
    return { entries: decodeEntries(payload), meta: null };
  }
  if (!isRecord(payload)) {
    throw new Error('Invalid collocation data: expected an array or object');
  }
  const list = payload.bigrams ?? payload.entries;
  if (!Array.isArray(list)) {
    throw new Error('Invalid collocation data: missing bigrams array');
  }
  return { entries: decodeEntries(list), meta: decodeMeta(payload.meta) };
}

export function getCollocationMeta(): CollocationMeta | null {
  return cachedMeta;
}

/** Inject a parsed table (boot wiring, playground, tests). */
export function setCollocationTable(
  entries: readonly CollocationEntry[],
  meta: CollocationMeta | null = null,
): void {
  cachedEntries = [...entries];
  cachedMeta = meta;
  loading = null;
  prepared = null;
}

/** Drop the cached table so the next load fetches again. */
export function resetCollocationTable(): void {
  cachedEntries = null;
  cachedMeta = null;
  loading = null;
  prepared = null;
}

function assetUrl(): string | null {
  const runtime = globalThis.chrome?.runtime;
  return typeof runtime?.getURL === 'function' ? runtime.getURL(ASSET_FILE) : null;
}

/**
 * Load the table once. Concurrent callers share one fetch; a successful load
 * is cached forever, while a failed one resolves to `[]` and can be retried.
 * Without `chrome.runtime` (Node, non-extension page) this resolves to `[]`.
 */
export function loadCollocationTable(
  options: LoadCollocationOptions = {},
): Promise<CollocationEntry[]> {
  if (cachedEntries) return Promise.resolve(cachedEntries);
  if (loading) return loading;

  const url = options.url ?? assetUrl();
  if (!url) return Promise.resolve([]);

  const fetchImpl = options.fetchImpl ?? globalThis.fetch;
  if (typeof fetchImpl !== 'function') return Promise.resolve([]);

  loading = (async () => {
    try {
      const decoded = decodeCollocationFile(
        await fetchExtensionJson(ASSET_FILE, fetchImpl, url),
      );
      cachedEntries = decoded.entries;
      cachedMeta = decoded.meta;
      return cachedEntries;
    } catch (error) {
      console.warn('[earworm] offline collocations unavailable:', error);
      return [] as CollocationEntry[];
    } finally {
      loading = null;
    }
  })();

  return loading;
}

function tableIndex(table: readonly CollocationEntry[]): CollocationIndex {
  const dictionary = getActiveDictionary();
  if (!prepared || prepared.table !== table || prepared.dictionary !== dictionary) {
    prepared = {
      table,
      dictionary,
      index: buildCollocationIndex(table, lemmatize),
    };
  }
  return prepared.index;
}

/**
 * Offline spans for one sentence, using the table loaded at boot. Returns `[]`
 * before the table arrives; callers that render immediately get a plain
 * sentence and can re-run after `loadCollocationTable()` resolves.
 *
 * The lemma index is cached and rebuilt only when the table or the active
 * dictionary instance changes, so loading the dictionary later still upgrades
 * matching without re-lemmatizing 9k entries per sentence.
 */
export function computeOfflineSpans(sentence: Sentence): CollocationSpan[] {
  const table = cachedEntries;
  if (!table || table.length === 0) return [];
  return matchIndexedCollocations(sentence.text, tableIndex(table));
}
